def text(key: str, language: AILanguage, **values: Any) -> str:
    return _TEXT[key][_LANGUAGE[language]].format(**values)


def guide(family: str, language: AILanguage) -> dict[str, Any]:
    profile = _GUIDES.get(family, _GUIDES["other_service"])
    result: dict[str, Any] = {
        key: value[_LANGUAGE[language]] for key, value in profile.items()
    }
    result.setdefault("uncertainty", text("correlation_limit", language))
    result["steps"] = [result["validate"], result["change"], result["verify"]]
    return result
